original_files.system/controlDict:
FoamFile { version 2.0; format ascii; class dictionary; object controlDict; }

application gasUGKP;
startFrom startTime;
startTime 0;
stopAt endTime;
endTime 1e-05;
deltaT 0.00001;
writeControl adjustableRunTime;
writeInterval 1.0000000000000002e-06;
purgeWrite 0;
writeFormat ascii;
writePrecision 17;
writeCompression off;
timeFormat general;
timePrecision 17;
runTimeModifiable false;
adjustTimeStep true;
maxCo 0.3;
maxDeltaT 0.00001;

original_files.system/fvSchemes:
FoamFile { version 2.0; format ascii; class dictionary; object fvSchemes; }

fluxScheme Kurganov;
gasLimiter barthJespersen;
ddtSchemes { default SSPRK2; }
gradSchemes { default Gauss linear; }
divSchemes
{
 default none;
 div(phi,U) Gauss MUSCL;
 div(phi,e) Gauss MUSCL;
 div(phi,K) Gauss MUSCL;
 div(phi,(p|rho)) Gauss MUSCL;
 div(((rho*nuEff)*dev2(T(grad(U))))) Gauss linear;
}
laplacianSchemes { default Gauss linear corrected; }
interpolationSchemes { default linear; }
snGradSchemes { default corrected; }

wallDist { method meshWave; }
